// ── 2. Nieve, lluvia, pétalos de sakura y luciérnagas: ambiente continuo ─────────────────────────
const nieve = P.crea({
  grupo: 'nieve', porSegundo: 55, radio: 13, alto: 11, fondo: 20,
  fuerza: 1.0, grav: 0.9,
  deriva: 0.7, derivaHz: 0.28,
  manto: 2, mantoEn: 50, mantoDura: 120, mantoRadio: 0,
  mantoDe: 'nieve',
  cuaja: false, dura: 6, desvanece: 3,
  vuelo: 30, parada: 0.25, rebote: 0.02, roza: 0.1, tope: 420,
