});
lluvia.porSegundo = 0;

// 🌸 Pétalos de Sakura del Santuario Zen
const petalosSakura = P.crea({
  grupo: 'petalos_sakura',
  porSegundo: 65,
  radio: 26,
  alto: 9,
  fondo: 16,
  fuerza: 0.9,
  grav: 1.1,
  deriva: 1.6,
  derivaHz: 0.3,
  dura: 16,
  desvanece: 4,
  vuelo: 22,
  posarse: true,
  muereEnFluido: false,
  colores: [
    [1.0, 0.72, 0.85],
    [0.98, 0.58, 0.76],
    [0.92, 0.45, 0.65],
    [1.0, 0.88, 0.94],
    [0.85, 0.35, 0.55]
  ]
});
petalosSakura.porSegundo = 0;

// 🏮 Luciérnagas Mágicas con Vuelo Curvilíneo 3D y Auto-Iluminación
if (game.voxelesUI && game.voxelesUI.material) {
  game.voxelesUI.material('luciernagas', { emite: true, luz: 10 });   // 10 = lo que el dueño dio por bueno (#134/#139): con 6 el color se pierde en la cuantización
}

window.LUC_CONFIG = window.LUC_CONFIG || {
  curvatura: 1.4,
  frecuencia: 0.35,
  ondulacionV: 0.45,
  velocidad: 0.85
};

const luciernagas = P.crea({
  grupo: 'luciernagas',
  porSegundo: 26,
  radio: 26,
  alto: 3.5,
  fondo: 6,
  fuerza: 0.0,
  grav: 0.0,
  deriva: 0.0,
  derivaHz: 0.0,
  dura: 16,
  desvanece: 4,
  vuelo: 20,
  posarse: false,
  colores: [
    [1.0, 0.95, 0.45],
    [0.92, 1.0, 0.55],
    [1.0, 0.85, 0.3],
    [1.0, 1.0, 0.8]
  ]
});
luciernagas.porSegundo = 0;

// Cinemática Orgánica 3D Totalmente Reactiva en Tiempo Real
const origSiembraLuc = luciernagas._siembra;
luciernagas._siembra = function(dt, ahora) {
  const cfg = window.LUC_CONFIG;
  const vel = (cfg && typeof cfg.velocidad === 'number' && !isNaN(cfg.velocidad)) ? Math.max(0.0, cfg.velocidad) : 0.85;
  if (vel <= 0.0001) return false;
  return origSiembraLuc.call(this, dt, ahora);
};

luciernagas._paso = function(dt, ahora) {
  const cfg = window.LUC_CONFIG;
  const vel = (cfg && typeof cfg.velocidad === 'number' && !isNaN(cfg.velocidad)) ? Math.max(0.0, cfg.velocidad) : 0.85;
  const freq = (cfg && typeof cfg.frecuencia === 'number' && !isNaN(cfg.frecuencia)) ? Math.max(0.01, cfg.frecuencia) : 0.35;
  const curv = (cfg && typeof cfg.curvatura === 'number' && !isNaN(cfg.curvatura)) ? Math.max(0.0, cfg.curvatura) : 1.4;
  const ondY = (cfg && typeof cfg.ondulacionV === 'number' && !isNaN(cfg.ondulacionV)) ? Math.max(0.0, cfg.ondulacionV) : 0.5;

  for (let i = this._V.length - 1; i >= 0; i--) {
    const g = this._V[i];
    if (vel > 0.0001) {
      if ((g.vuela = (g.vuela || 0) + (dt * vel)) > this.vuelo) {
        this._V.splice(i, 1);
        continue;
      }
    }

    if (g.cx == null) {
      g.faseX = Math.random() * 10;
      g.faseZ = Math.random() * 10;
      g.faseY = Math.random() * 10;
      g.rumboX = (Math.random() - 0.5) * 0.35;
      g.rumboZ = (Math.random() - 0.5) * 0.35;
      g.tLocal = 0;
      const tt0 = 0;
      const offX0 = (Math.sin(tt0 * 0.85 + g.faseX) * 1.8 * curv) + (Math.cos(tt0 * 0.35 + g.faseZ) * 0.9 * curv);
      const offZ0 = (Math.cos(tt0 * 0.75 + g.faseZ) * 1.8 * curv) + (Math.sin(tt0 * 0.40 + g.faseX) * 0.9 * curv);
      const offY0 = (Math.sin(tt0 * 1.25 + g.faseY) * 0.75 * ondY);
      g.cx = g.x - offX0;
      g.cy = g.y - offY0;
      g.cz = g.z - offZ0;
    }

    g.tLocal = (g.tLocal || 0) + (dt * vel);
    const tt = g.tLocal * freq * 2.0 * Math.PI;

    g.cx += g.rumboX * dt * vel;
    g.cz += g.rumboZ * dt * vel;

    g.x = g.cx + (Math.sin(tt * 0.85 + g.faseX) * 1.8 * curv) + (Math.cos(tt * 0.35 + g.faseZ) * 0.9 * curv);
    g.z = g.cz + (Math.cos(tt * 0.75 + g.faseZ) * 1.8 * curv) + (Math.sin(tt * 0.40 + g.faseX) * 0.9 * curv);
    g.y = g.cy + (Math.sin(tt * 1.25 + g.faseY) * 0.75 * ondY);

    const vidaRestante = this.vuelo - (g.vuela || 0);
    g.f = vidaRestante < this.desvanece ? Math.max(0.05, vidaRestante / this.desvanece) : 1.0;
  }
  return true;
};

// Renderizado Sub-Vóxel Continuo en la GPU sin escalones
if (!window.__patchedSubVoxelUI) {
  window.__patchedSubVoxelUI = true;
  const origVoxUIGeom = window.mcVoxUIGeom;

  window.mcVoxUIGeom = function() {
    if (!mc.voxUISucio && mc.voxUIArr) return mc.voxUIArr;
    const P_SYS = window.__vfParticulas && window.__vfParticulas.sistemas;
    const lucSys = P_SYS && P_SYS.find(s => s.grupo === 'luciernagas');
    if (!lucSys || !lucSys._V || !lucSys._V.length) {
      return origVoxUIGeom ? origVoxUIGeom() : null;
    }

    const paso = MC_VOX * Math.max(1, mc.voxUITam | 0);
    let total = 0;
    if (mc.voxUI) for (const [nombre, m] of mc.voxUI) total += m.size;
    total += lucSys._V.length;
    const cap = total * 36 * 7;
    let buf = mc._voxUIBuf;
    if (!buf || buf.length < cap) buf = mc._voxUIBuf = new Float32Array(Math.max(cap, 4096));
    let n = 0;

    if (mc.voxUI) {
      for (const [nombre, m] of mc.voxUI) {
        if (nombre === 'luciernagas') continue;
        const lado = paso * mcVoxUIGrosor(nombre);
        for (const [k, c] of m) {
          const q = k.split(','), x = +q[0], y = +q[1], z = +q[2];
          n = mcPushVoxCuboBuf(buf, n, x * paso, y * paso, z * paso, lado, c[0], c[1], c[2], 63);
        }
      }
    }

    const ladoL = paso * mcVoxUIGrosor('luciernagas');
    const t = performance.now() / 1000;
    for (let i = 0; i < lucSys._V.length; i++) {
      const g = lucSys._V[i];
      const c = g.col, f = g.f === undefined ? 1 : g.f;
      const pulso = 0.85 + 0.15 * Math.sin(t * 3.0 + (g.faseX || 0));
      n = mcPushVoxCuboBuf(buf, n, g.x - ladoL * 0.5, g.y - ladoL * 0.5, g.z - ladoL * 0.5, ladoL, c[0] * f * pulso, c[1] * f * pulso, c[2] * f * pulso, 63);
    }

    mc.voxUISucio = false;
    mc.voxUIArr = buf.subarray(0, n);
    return mc.voxUIArr;
  };
}

// ── 3. Estrellas: capa de voxeles autoiluminada ──────────────────────────────────────────────────
const estrellas = {
  n: 240, radio: 78, altura: 24, grupo: 'estrellas', titila: true, _t: 0, _on: false,
  grosor: 4,
  enciende(grosor){
    if(grosor) this.grosor = grosor;
    const U = game.voxelesUI, p = 1 / 16;
    U.limpia(this.grupo);
    U.grosor(this.grupo, this.grosor);
    U.material(this.grupo, { emite: false });
    const cx = mc.dim ? mc.dim.x / 2 : mc.pos[0], cz = mc.dim ? mc.dim.z / 2 : mc.pos[2];
    for(let i = 0; i < this.n; i++){
      const t = Math.random() * Math.PI * 2, u = Math.random(), r = this.radio * Math.sqrt(u);
      const alt = this.altura + Math.sqrt(Math.max(0, 1 - u)) * 26;
      const b = 0.55 + Math.random() * 0.45;
      const tinte = Math.random();
      const col = tinte > 0.88 ? [b*0.75, b*0.85, b] : (tinte < 0.08 ? [b, b*0.86, b*0.7] : [b, b, b]);
      U.pon(Math.round((cx + Math.cos(t) * r) / p), Math.round(alt / p),
            Math.round((cz + Math.sin(t) * r) / p), col, this.grupo);
    }
    this._on = true;
    return this.n;
  },
  apaga(){ game.voxelesUI.limpia(this.grupo); this._on = false; return 0; }
};

// ── 4. Las teclas ────────────────────────────────────────────────────────────────────────────────
function enLaMira(){
  if(typeof mcRaycast === 'function'){
    const h = mcRaycast(6, true);
    if(h && h.cell) return [h.cell[0] + 0.5, h.cell[1] + 1.1, h.cell[2] + 0.5];
  }
  const cp = Math.cos(mc.pitch || 0);
  return [mc.pos[0] - Math.sin(mc.yaw||0) * cp * 3,
          mc.pos[1] + 1.2 + Math.sin(mc.pitch||0) * 3,
          mc.pos[2] - Math.cos(mc.yaw||0) * cp * 3];
}

function conmuta(sis, ps, nombre, icono){
  if(sis.porSegundo){ sis.para(); sis.limpia(); toast(icono + ' ' + nombre + ' — parada'); return false; }
  sis.enciende(ps); toast(icono + ' ' + nombre + ' — ' + ps + ' por segundo (misma tecla para parar)');
  return true;
}

game.onKey('y', () => { chispas.salpica(enLaMira()); });
game.onKey('m', () => { polvo.salpica(enLaMira()); });
game.onKey('t', () => { hojas.salpica(enLaMira()); });
game.onKey('h', () => { humo.salpica(enLaMira()); });
game.onKey('v', () => conmuta(nieve, 55, 'Nieve', '❄️'));
game.onKey('l', () => conmuta(lluvia, 150, 'Lluvia', '🌧️'));
game.onKey('p', () => conmuta(petalosSakura, 65, 'Pétalos Sakura', '🌸'));
game.onKey('j', () => conmuta(luciernagas, 26, 'Luciérnagas', '🏮'));
game.onKey('c', () => {
  if(estrellas._on){ estrellas.apaga(); toast('✨ Estrellas — fuera'); }
  else { estrellas.enciende();
    toast('✨ ' + estrellas.n + ' estrellas de grosor ' + estrellas.grosor + ' · ' + estrellas.n +
          ' voxeles (el grosor sale gratis) · game.efectos.estrellas.grosor = 16 y C', 4); }
});

game.efectos = {
  chispas, polvo, hojas, humo, nieve, lluvia, petalosSakura, luciernagas, estrellas,
  info(){
    return {
      sistemas: P.info(),
      estrellas: estrellas._on ? estrellas.n : 0,
      capa: game.voxelesUI.info()
    };
  },
  para(){
    nieve.para();
    lluvia.para();
    petalosSakura.para();
    luciernagas.para();
    P.limpia();
    estrellas.apaga();
    return 'todo apagado';
  }
};

toast('✨ Efectos listos · C estrellas · V nieve · L lluvia · P sakura 🌸 · J luciérnagas 🏮 · Y/M/T/H impacto');

return { estrellas, lluvia, nieve, petalosSakura, luciernagas, efectos: game.efectos };
